// Package apiconv converts between the protobuf API types and the domain
// (store/core) types.
//
// The field-by-field mapping is generated by goverter into gen/ from the
// Converter interface below; this file holds only the interface and the
// hand-written rules goverter calls through `extend` (enums, etags,
// timestamps, ranges).
package apiconv

//go:generate rm -rf gen
//go:generate go run github.com/jmattheis/goverter/cmd/goverter@v1.11.1 gen .

import (
	"fmt"
	"strconv"
	"time"

	"google.golang.org/protobuf/types/known/timestamppb"

	adminv1 "github.com/jacobalberty/beenfar/api/gen/go/beenfar/admin/v1"
	configv1 "github.com/jacobalberty/beenfar/api/gen/go/beenfar/config/v1"
	"github.com/jacobalberty/beenfar/internal/core"
	"github.com/jacobalberty/beenfar/internal/store"
)

// Converter is implemented by gen/ (package apiconvgen) as plain functions.
//
// Field names differ only in initialism case (Id/ID, Ssid/SSID, VlanId/VLANID),
// hence matchIgnoreCase. Protobuf's unexported bookkeeping fields (state,
// sizeCache, unknownFields) are left zero, which is correct for new messages.
//
// goverter:converter
// goverter:output:file ./gen/apiconv.go
// goverter:output:package github.com/jacobalberty/beenfar/internal/apiconv/gen:apiconvgen
// goverter:output:format function
// goverter:matchIgnoreCase
// goverter:ignoreUnexported
// goverter:useZeroValueOnPointerInconsistency
// goverter:extend Timestamp WifiSecurityToProto WifiSecurityFromProto WifiBandToProto WifiBandFromProto
// goverter:extend DeviceStateToProto ReadoptionToProto AdapterKindToProto UserSourceToProto VLANToProto VLANFromProto
// goverter:extend SwitchPortTaggingToProto SwitchPortTaggingFromProto PoEModeToProto PoEModeFromProto
type Converter interface {
	// goverter:map Revision Etag | Etag
	WifiToProto(store.WifiNetwork) *configv1.WifiNetwork
	// goverter:map Etag Revision | ParseEtag
	// goverter:ignore CreateTime UpdateTime
	WifiFromProto(*configv1.WifiNetwork) (store.WifiNetwork, error)

	// goverter:map Revision Etag | Etag
	NetworkToProto(store.Network) *configv1.Network
	// goverter:map Etag Revision | ParseEtag
	// goverter:ignore CreateTime UpdateTime
	NetworkFromProto(*configv1.Network) (store.Network, error)

	// The shared secret is input-only: it is never returned.
	// goverter:map Revision Etag | Etag
	// goverter:map SecretVersion SharedSecretVersion
	// goverter:map AuthPort AuthPort | PortToProto
	// goverter:map AccountingPort AccountingPort | PortToProto
	// goverter:ignore SharedSecret
	RadiusToProto(store.RadiusServer) *configv1.RadiusServer
	// goverter:map Etag Revision | ParseEtag
	// goverter:map AuthPort AuthPort | PortFromProto
	// goverter:map AccountingPort AccountingPort | PortFromProto
	// goverter:ignore CreateTime UpdateTime SecretVersion
	RadiusFromProto(*configv1.RadiusServer) (store.RadiusServer, error)

	// goverter:map Revision Etag | Etag
	// goverter:map PortIndex PortIndex | PortToProto
	SwitchPortToProto(store.SwitchPort) *configv1.SwitchPort
	// goverter:map Etag Revision | ParseEtag
	// goverter:map PortIndex PortIndex | PortFromProto
	// goverter:ignore CreateTime UpdateTime
	SwitchPortFromProto(*configv1.SwitchPort) (store.SwitchPort, error)

	// goverter:map LastSeen LastSeenTime
	DeviceToProto(store.Device) *configv1.Device
	DevicesToProto([]store.Device) []*configv1.Device

	// goverter:map Revision Etag | Etag
	UserToProto(store.User) *adminv1.User

	// goverter:map Prefix | TokenPrefix
	APITokenToProto(store.APIToken) *adminv1.ApiToken

	AdapterToProto(core.AdapterStatus) *adminv1.Adapter
}

// Etag renders a store revision. Clients must treat etags as opaque.
func Etag(revision int64) string { return strconv.FormatInt(revision, 10) }

// ParseEtag maps an etag to a revision. Empty means "no check" (0).
func ParseEtag(s string) (int64, error) {
	if s == "" {
		return 0, nil
	}
	n, err := strconv.ParseInt(s, 10, 64)
	if err != nil || n < 1 {
		return 0, fmt.Errorf("%w: malformed etag %q", store.ErrInvalid, s)
	}
	return n, nil
}

// Timestamp maps the zero time to an unset field.
func Timestamp(t time.Time) *timestamppb.Timestamp {
	if t.IsZero() {
		return nil
	}
	return timestamppb.New(t)
}

// TokenPrefix shows the token prefix as it appears at the start of the secret.
func TokenPrefix(p string) string { return "bf_" + p }

func VLANToProto(v int) uint32 { return uint32(v) } //nolint:gosec // 0-4094, enforced on write

func VLANFromProto(v uint32) (int, error) {
	if v > 4094 {
		return 0, fmt.Errorf("%w: vlan_id must be 0 (untagged) or 1-4094", store.ErrInvalid)
	}
	return int(v), nil
}

func PortToProto(v int) uint32 { return uint32(v) } //nolint:gosec // 0-65535, enforced on write

func PortFromProto(v uint32) (int, error) {
	if v > 65535 {
		return 0, fmt.Errorf("%w: port numbers must be at most 65535", store.ErrInvalid)
	}
	return int(v), nil
}

