// biMap maps proto enum values (P) to domain values (D). The zero proto value
// (UNSPECIFIED) maps to the zero domain value and back.
type biMap[P, D comparable] map[P]D

func (m biMap[P, D]) toProto(d D) P {
	for p, v := range m {
		if v == d {
			return p
		}
	}
	var zero P
	return zero
}

func (m biMap[P, D]) fromProto(p P, field string) (D, error) {
	var zero P
	if p == zero {
		var d D
		return d, nil
	}
	d, ok := m[p]
	if !ok {
		return d, fmt.Errorf("%w: unknown %s %v", store.ErrInvalid, field, p)
	}
	return d, nil
}

func WifiSecurityToProto(s store.WifiSecurity) configv1.WifiSecurity { return wifiSecurity.toProto(s) }

func WifiSecurityFromProto(s configv1.WifiSecurity) (store.WifiSecurity, error) {
	return wifiSecurity.fromProto(s, "security")
}

func WifiBandToProto(b store.WifiBand) configv1.WifiBand { return wifiBand.toProto(b) }

func WifiBandFromProto(b configv1.WifiBand) (store.WifiBand, error) {
	return wifiBand.fromProto(b, "band")
}

func SwitchPortTaggingToProto(t store.SwitchPortTagging) configv1.SwitchPortTagging {
	return switchPortTagging.toProto(t)
}

func SwitchPortTaggingFromProto(t configv1.SwitchPortTagging) (store.SwitchPortTagging, error) {
	return switchPortTagging.fromProto(t, "tagging")
}

func PoEModeToProto(m store.PoEMode) configv1.PoeMode { return poeMode.toProto(m) }

func PoEModeFromProto(m configv1.PoeMode) (store.PoEMode, error) {
	return poeMode.fromProto(m, "poe_mode")
}

func DeviceStateToProto(s store.DeviceState) configv1.DeviceState { return deviceState.toProto(s) }

// DeviceStateFromProto is used for list filters; unspecified matches all.
func DeviceStateFromProto(s configv1.DeviceState) (store.DeviceState, error) {
	return deviceState.fromProto(s, "state")
}

func ReadoptionToProto(r store.Readoption) configv1.ReadoptionState { return readoption.toProto(r) }

func AdapterKindToProto(k core.AdapterKind) adminv1.AdapterKind { return adapterKind.toProto(k) }

func UserSourceToProto(s store.UserSource) adminv1.UserSource { return userSource.toProto(s) }
